import json

# Re-submit histogram approach
def make_3x3_histogram(grid):
    n = len(grid)
    hist = [[0]*3 for _ in range(3)]
    for r in range(n):
        for c in range(n):
            if grid[r][c] != 6:
                hist[r//3][c//3] += 1
    return hist

